// Vrai correctif XI Type (merci d'avoir trouve toi-meme la cause !) :
// les joueurs de la liste XI n'ont que leur NOM DE FAMILLE enregistre comme
// reponse valide (ex: "Donnarumma"), mais les suggestions de saisie
// affichent le PRENOM + NOM complet ("Gianluigi Donnarumma") pris depuis la
// base generale des joueurs - taper ou selectionner cette suggestion ne
// validait donc jamais. Corrige dans les deux modes XI Type (duel ET solo) :
// desormais le prenom+nom complet est accepte en plus du nom de famille
// seul.
//
// Combine avec le diagnostic pour le bug d'invitation Liste (pas encore
// applique de ton cote) pour n'avoir qu'un seul patch a lancer.
//
// Pas de nouvelle dependance, part par eas update, pas besoin de nouveau
// build.
//
// A appliquer depuis la racine du repo OU depuis strikr-app :
//   node patch-xi-realfix-combined.js
//   git add -A
//   git commit -m "Corrige la validation des reponses XI Type (prenom+nom accepte) et ajoute le diagnostic invitation Liste"
//   git push -u origin main
//   cd strikr-app
//   eas update --branch production --platform ios
//   eas update --branch production --platform android

const fs = require('fs');
const path = require('path');

function resolveBase() {
  const candidates = [path.join(__dirname, 'strikr-app'), __dirname];
  for (const c of candidates) {
    if (fs.existsSync(path.join(c, 'package.json')) && fs.existsSync(path.join(c, 'App.tsx'))) {
      return c;
    }
  }
  throw new Error(
    "Impossible de trouver le dossier strikr-app (avec package.json et App.tsx dedans). " +
    "Lance ce script depuis la racine du repo (a cote du dossier strikr-app) ou depuis l'interieur de strikr-app."
  );
}
const BASE = resolveBase();
console.log('dossier detecte :', BASE);

function write(rel, content) {
  const full = path.join(BASE, rel);
  fs.mkdirSync(path.dirname(full), { recursive: true });
  fs.writeFileSync(full, content);
  console.log('wrote', rel);
}

write("src/game/useXIDuel.ts", "// \"XI Type\" duel: name the starting eleven of a famous match, alternating\n// turns with a friend (unlike Mode Liste's duel, which has both players\n// racing simultaneously) — each correct name is worth 1 point, most points\n// once all 11 are found wins. Mirrors useDuel.ts's grid-duel plumbing\n// closely (invite/accept/decline/turn timer/forfeit), swapping the 3x3 grid\n// mechanics for a plain named list.\nimport { useCallback, useEffect, useRef, useState } from 'react';\nimport { RealtimeChannel } from '@supabase/supabase-js';\nimport AsyncStorage from '@react-native-async-storage/async-storage';\nimport { supabase } from '../lib/supabase';\nimport { useAuth } from '../state/auth';\nimport { useDiamonds } from '../state/diamonds';\nimport { useStats } from '../state/stats';\nimport { logEvent } from '../lib/analytics';\nimport { fx } from '../lib/fx';\nimport { stripAcc } from './engine';\nimport { XI_MATCHES } from '../data/xiMatches';\nimport { playerFull, playerBase, playerPhoto } from '../data/quizLists';\n\nexport type XIDuelRole = 'creator' | 'opponent';\n\nexport interface XIFoundEntry {\n  index: number;\n  by: XIDuelRole;\n  name: string;\n}\n\nexport interface XIDuelRow {\n  id: string;\n  code: string;\n  match_id: string;\n  match_title: string;\n  creator_id: string;\n  opponent_id: string | null;\n  creator_name: string | null;\n  opponent_name: string | null;\n  found: XIFoundEntry[];\n  turn: XIDuelRole;\n  creator_score: number;\n  opponent_score: number;\n  status: 'invited' | 'waiting' | 'active' | 'finished' | 'declined';\n  winner: XIDuelRole | 'draw' | null;\n  turn_started_at: string;\n}\n\nexport const XI_DUEL_TURN_SECONDS = 45;\n\n// Same reward economy as the Grille duel — nothing for a loss, capped per\n// day so ping-ponging duels back and forth can't become an unlimited\n// diamond faucet.\nconst WIN_REWARD = 6;\nconst DRAW_REWARD = 3;\nconst WIN_XP = 40;\nconst DRAW_XP = 15;\nconst REWARDED_PER_DAY = 5;\nconst STORAGE_KEY = 'strikr_xi_duel_rewards_v1';\n\nfunction todayStr(): string {\n  return new Date().toISOString().slice(0, 10);\n}\n\n// Letters only: the on-screen keyboard has no hyphen/apostrophe keys, but\n// real surnames do (\"Alexander-Arnold\", \"Guivarc'h\") — without this, those\n// players could never be typed correctly no matter what's entered.\nfunction norm(s: string): string {\n  return stripAcc(s.trim().toLowerCase()).replace(/[^a-z]/g, '');\n}\n\nexport function useXIDuel() {\n  const { user } = useAuth();\n  const { addDiamonds } = useDiamonds();\n  const { recordWin } = useStats();\n  const [duel, setDuel] = useState<XIDuelRow | null>(null);\n  const [loading, setLoading] = useState(true);\n  const channelRef = useRef<RealtimeChannel | null>(null);\n  const rewardedDuelRef = useRef<string | null>(null);\n  const [rewardedToday, setRewardedToday] = useState(0);\n  const [lastReward, setLastReward] = useState(0);\n\n  useEffect(() => {\n    AsyncStorage.getItem(STORAGE_KEY).then((raw) => {\n      if (!raw) return;\n      try {\n        const parsed = JSON.parse(raw);\n        if (parsed.date === todayStr()) setRewardedToday(parsed.count || 0);\n      } catch {\n        // ignore corrupt storage\n      }\n    });\n  }, []);\n\n  const loadActive = useCallback(async () => {\n    if (!user) {\n      setDuel(null);\n      setLoading(false);\n      return;\n    }\n    setLoading(true);\n    const { data } = await supabase\n      .from('xi_duels')\n      .select('*')\n      .or(`creator_id.eq.${user.id},opponent_id.eq.${user.id}`)\n      .in('status', ['waiting', 'active', 'invited', 'declined'])\n      .order('created_at', { ascending: false })\n      .limit(1)\n      .maybeSingle();\n    setDuel((data as XIDuelRow | null) || null);\n    setLoading(false);\n  }, [user]);\n\n  useEffect(() => {\n    loadActive();\n  }, [loadActive]);\n\n  // Separate from the per-duel channel below (which only exists once a duel\n  // is already loaded) — this one is keyed by user id so an incoming invite\n  // shows up immediately if the invitee is already sitting on this screen.\n  useEffect(() => {\n    if (!user) return;\n    const channel = supabase\n      .channel(`xi-duel-invites-${user.id}`)\n      .on(\n        'postgres_changes',\n        { event: 'INSERT', schema: 'public', table: 'xi_duels', filter: `opponent_id=eq.${user.id}` },\n        () => loadActive()\n      )\n      .subscribe();\n    return () => {\n      supabase.removeChannel(channel);\n    };\n  }, [user, loadActive]);\n\n  useEffect(() => {\n    if (channelRef.current) {\n      supabase.removeChannel(channelRef.current);\n      channelRef.current = null;\n    }\n    if (!duel) return;\n    const channel = supabase\n      .channel(`xi-duel-${duel.id}`)\n      .on(\n        'postgres_changes',\n        { event: 'UPDATE', schema: 'public', table: 'xi_duels', filter: `id=eq.${duel.id}` },\n        (payload) => setDuel(payload.new as XIDuelRow)\n      )\n      .subscribe();\n    channelRef.current = channel;\n    return () => {\n      supabase.removeChannel(channel);\n      channelRef.current = null;\n    };\n  }, [duel?.id]);\n\n  // Fires once per finished duel (guarded by rewardedDuelRef) regardless of\n  // which client actually made the winning move — both participants land\n  // here via their own realtime update and credit themselves independently.\n  useEffect(() => {\n    if (!duel || !user || duel.status !== 'finished') return;\n    if (rewardedDuelRef.current === duel.id) return;\n    rewardedDuelRef.current = duel.id;\n    const role = duel.creator_id === user.id ? 'creator' : 'opponent';\n    const won = duel.winner === role;\n    const draw = duel.winner === 'draw';\n    if (!won && !draw) return;\n    const reward = won ? WIN_REWARD : DRAW_REWARD;\n    if (rewardedToday < REWARDED_PER_DAY) {\n      addDiamonds(reward);\n      setLastReward(reward);\n      setRewardedToday((prev) => {\n        const next = prev + 1;\n        AsyncStorage.setItem(STORAGE_KEY, JSON.stringify({ date: todayStr(), count: next })).catch(() => {});\n        return next;\n      });\n    } else {\n      setLastReward(0);\n    }\n    recordWin({ kind: 'duel', firstTry: won, xp: won ? WIN_XP : DRAW_XP });\n    fx.win();\n  }, [duel, user, rewardedToday, addDiamonds, recordWin]);\n\n  const myRole = useCallback(\n    (d: XIDuelRow): XIDuelRole => (d.creator_id === user?.id ? 'creator' : 'opponent'),\n    [user]\n  );\n\n  const inviteXIDuel = useCallback(\n    async (targetUserId: string, targetName: string, matchId: string, matchTitle: string): Promise<{ error: string | null }> => {\n      if (!user) return { error: 'not_authenticated' };\n      const { data, error } = await supabase.rpc('invite_xi_duel', {\n        target_user_id: targetUserId,\n        target_name: targetName,\n        match_id_arg: matchId,\n        match_title_arg: matchTitle,\n      });\n      if (error) return { error: error.message };\n      const newId = Array.isArray(data) ? data[0]?.id : null;\n      if (newId) await loadActive();\n      logEvent(user.id, 'xi_duel_invite_sent');\n      return { error: null };\n    },\n    [user, loadActive]\n  );\n\n  const respondInvite = useCallback(\n    async (accept: boolean): Promise<{ error: string | null }> => {\n      if (!duel || !user) return { error: 'no_duel' };\n      const { error } = await supabase.rpc('respond_xi_duel_invite', { duel_id: duel.id, accept });\n      if (error) return { error: error.message };\n      if (accept) {\n        await loadActive();\n      } else {\n        setDuel(null);\n      }\n      logEvent(user.id, accept ? 'xi_duel_invite_accepted' : 'xi_duel_invite_declined');\n      return { error: null };\n    },\n    [duel, user, loadActive]\n  );\n\n  const guessName = useCallback(\n    async (raw: string): Promise<{ error: string | null }> => {\n      if (!duel || !user) return { error: 'no_duel' };\n      if (duel.status !== 'active') {\n        logEvent(user.id, 'xi_duel_guess_diagnostic', { reason: 'not_active', raw, duel_status: duel.status, match_id: duel.match_id });\n        return { error: 'not_active' };\n      }\n      const role = myRole(duel);\n      if (duel.turn !== role) {\n        logEvent(user.id, 'xi_duel_guess_diagnostic', { reason: 'not_your_turn', raw, turn: duel.turn, role, match_id: duel.match_id });\n        return { error: 'not_your_turn' };\n      }\n      const match = XI_MATCHES.find((m) => m.id === duel.match_id);\n      if (!match) {\n        logEvent(user.id, 'xi_duel_guess_diagnostic', { reason: 'match_not_found', raw, match_id: duel.match_id });\n        return { error: 'invalid_answer' };\n      }\n\n      const input = norm(raw);\n      if (!input) return { error: 'invalid_answer' };\n\n      const foundIndexes = new Set(duel.found.map((f) => f.index));\n      const baseCounts = new Map<string, number>();\n      match.players.forEach((p) => {\n        const b = norm(playerBase(p));\n        baseCounts.set(b, (baseCounts.get(b) || 0) + 1);\n      });\n      const idx = match.players.findIndex((p, i) => {\n        if (foundIndexes.has(i)) return false;\n        const full = norm(playerFull(p));\n        const base = norm(playerBase(p));\n        if (input === full) return true;\n        if (input === base && (baseCounts.get(base) || 0) === 1) return true;\n        // XI Type entries store just the surname as full/base (e.g.\n        // \"Donnarumma\"), with the real first+last name in `photo` — but the\n        // autocomplete suggestions pull from the global player database,\n        // which shows/inserts the full \"Gianluigi Donnarumma\" form. Typing\n        // or tapping that suggestion could never validate without this:\n        // only the bare surname ever worked.\n        const photo = playerPhoto(p);\n        if (photo && input === norm(photo)) return true;\n        return false;\n      });\n      if (idx === -1) {\n        // Distinguishes \"genuinely not one of the 11\" from \"correct name but\n        // already claimed\" — both used to look identical from the outside\n        // (same generic rejection), which made a real report impossible to\n        // diagnose without this. Reported once, not on every keystroke, so\n        // it can't spam app_events.\n        const alreadyFoundMatch = match.players.some(\n          (p, i) => foundIndexes.has(i) && (norm(playerFull(p)) === input || norm(playerBase(p)) === input)\n        );\n        logEvent(user.id, 'xi_duel_guess_diagnostic', {\n          reason: alreadyFoundMatch ? 'already_found' : 'no_match',\n          raw,\n          normalized: input,\n          match_id: duel.match_id,\n          roster: match.players.map((p) => norm(playerFull(p))),\n          found_indexes: Array.from(foundIndexes),\n        });\n        return { error: 'invalid_answer' };\n      }\n\n      const name = playerFull(match.players[idx]);\n      const nextFound = [...duel.found, { index: idx, by: role, name }];\n      const isDone = nextFound.length === match.players.length;\n      const creatorScore = duel.creator_score + (role === 'creator' ? 1 : 0);\n      const opponentScore = duel.opponent_score + (role === 'opponent' ? 1 : 0);\n      const nextTurn: XIDuelRole = role === 'creator' ? 'opponent' : 'creator';\n      const winner = isDone ? (creatorScore > opponentScore ? 'creator' : opponentScore > creatorScore ? 'opponent' : 'draw') : null;\n\n      const update = {\n        found: nextFound,\n        creator_score: creatorScore,\n        opponent_score: opponentScore,\n        turn: isDone ? duel.turn : nextTurn,\n        status: isDone ? ('finished' as const) : ('active' as const),\n        winner,\n        turn_started_at: new Date().toISOString(),\n      };\n      const { error } = await supabase.from('xi_duels').update(update).eq('id', duel.id).eq('turn', role);\n      if (error) return { error: error.message };\n      setDuel({ ...duel, ...update });\n      if (isDone) logEvent(user.id, 'xi_duel_finished', { result: winner });\n      return { error: null };\n    },\n    [duel, user, myRole]\n  );\n\n  // Called by whichever client is on the clock when its local 45s countdown\n  // hits zero — passes the turn without scoring. Guarded by `turn` still\n  // matching the caller's role so a stale timer firing after the opponent\n  // already moved (or after this player moved) can't double-pass.\n  const passTurn = useCallback(async (): Promise<void> => {\n    if (!duel || duel.status !== 'active') return;\n    const role = myRole(duel);\n    if (duel.turn !== role) return;\n    const nextTurn: XIDuelRole = role === 'creator' ? 'opponent' : 'creator';\n    const update = { turn: nextTurn, turn_started_at: new Date().toISOString() };\n    const { error } = await supabase.from('xi_duels').update(update).eq('id', duel.id).eq('turn', role);\n    if (!error) setDuel({ ...duel, ...update });\n  }, [duel, myRole]);\n\n  // Either participant can bail out — the other is credited a win rather\n  // than leaving the duel stuck forever with no timeout mechanism.\n  const forfeit = useCallback(async (): Promise<void> => {\n    if (!duel || !user) return;\n    const role = myRole(duel);\n    const otherRole: XIDuelRole = role === 'creator' ? 'opponent' : 'creator';\n    await supabase.from('xi_duels').update({ status: 'finished', winner: otherRole }).eq('id', duel.id);\n    setDuel(null);\n  }, [duel, user, myRole]);\n\n  const clearFinished = useCallback(() => setDuel(null), []);\n\n  // Distinct from forfeit(): an unanswered invite has no game to forfeit,\n  // so marking it \"declined\" (rather than a forfeit loss with a winner that\n  // never played) is the accurate outcome for the invitee to see.\n  const cancelInvite = useCallback(async (): Promise<void> => {\n    if (!duel) return;\n    await supabase.from('xi_duels').update({ status: 'declined', updated_at: new Date().toISOString() }).eq('id', duel.id);\n    setDuel(null);\n  }, [duel]);\n\n  const match = duel ? XI_MATCHES.find((m) => m.id === duel.match_id) || null : null;\n\n  return {\n    duel,\n    match,\n    loading,\n    myRole: duel ? myRole(duel) : null,\n    inviteXIDuel,\n    respondInvite,\n    cancelInvite,\n    guessName,\n    passTurn,\n    forfeit,\n    clearFinished,\n    refresh: loadActive,\n    lastReward,\n    rewardedToday,\n    rewardedLimit: REWARDED_PER_DAY,\n  };\n}\n");
write("src/game/useQuizList.ts", "// \"Mode Liste\": given a themed roster (see data/quizLists.ts), name as many\n// of its players as possible before a user-chosen timer runs out.\nimport { useCallback, useEffect, useRef, useState } from 'react';\nimport AsyncStorage from '@react-native-async-storage/async-storage';\nimport { useDiamonds } from '../state/diamonds';\nimport { useStats } from '../state/stats';\nimport { fx } from '../lib/fx';\nimport { stripAcc } from '../game/engine';\nimport { QUIZ_LISTS, QuizList, playerFull, playerBase, playerPhoto } from '../data/quizLists';\nimport { XI_MATCHES } from '../data/xiMatches';\n\nexport type QuizStatus = 'idle' | 'playing' | 'finished';\n\nexport const QUIZ_WIN_XP = 60;\nexport const QUIZ_REWARD_PER_PLAYER = 3;\nconst WIN_XP = QUIZ_WIN_XP;\nconst REWARD_PER_PLAYER = QUIZ_REWARD_PER_PLAYER;\nconst REWARDED_PER_DAY = 5;\nconst STORAGE_KEY = 'strikr_quiz_list_rewards_v1';\n\n// Letters only: the on-screen keyboard has no hyphen/apostrophe keys, but\n// real surnames do (\"Alexander-Arnold\", \"Guivarc'h\") — without this, those\n// players could never be typed correctly no matter what's entered.\nfunction norm(s: string): string {\n  return stripAcc(s.trim().toLowerCase()).replace(/[^a-z]/g, '');\n}\n\nfunction todayStr(): string {\n  return new Date().toISOString().slice(0, 10);\n}\n\nexport function useQuizList() {\n  const { addDiamonds } = useDiamonds();\n  const { recordWin } = useStats();\n  const [list, setList] = useState<QuizList | null>(null);\n  const [foundIndexes, setFoundIndexes] = useState<number[]>([]);\n  const [status, setStatus] = useState<QuizStatus>('idle');\n  const [timeLeft, setTimeLeft] = useState(0);\n  const [rewardedToday, setRewardedToday] = useState(0);\n  const [lastReward, setLastReward] = useState(0);\n  const durationRef = useRef(0);\n\n  useEffect(() => {\n    AsyncStorage.getItem(STORAGE_KEY).then((raw) => {\n      if (!raw) return;\n      try {\n        const parsed = JSON.parse(raw);\n        if (parsed.date === todayStr()) setRewardedToday(parsed.count || 0);\n      } catch {\n        // ignore corrupt storage\n      }\n    });\n  }, []);\n\n  const rewardsExhausted = rewardedToday >= REWARDED_PER_DAY;\n\n  const finishRound = useCallback(\n    (foundCount: number) => {\n      setStatus('finished');\n      if (foundCount > 0) {\n        const reward = foundCount * REWARD_PER_PLAYER;\n        if (!rewardsExhausted) {\n          addDiamonds(reward);\n          setLastReward(reward);\n          setRewardedToday((prev) => {\n            const next = prev + 1;\n            AsyncStorage.setItem(STORAGE_KEY, JSON.stringify({ date: todayStr(), count: next })).catch(() => {});\n            return next;\n          });\n        }\n        recordWin({ kind: 'game', firstTry: false, xp: WIN_XP });\n      }\n      fx.win();\n    },\n    [addDiamonds, recordWin, rewardsExhausted]\n  );\n\n  // Countdown ticks once a round is playing; ends the round at zero.\n  useEffect(() => {\n    if (status !== 'playing') return;\n    const id = setInterval(() => {\n      setTimeLeft((prev) => {\n        if (prev <= 1) {\n          clearInterval(id);\n          return 0;\n        }\n        return prev - 1;\n      });\n    }, 1000);\n    return () => clearInterval(id);\n  }, [status]);\n\n  useEffect(() => {\n    if (status === 'playing' && timeLeft === 0) {\n      finishRound(foundIndexes.length);\n    }\n  }, [status, timeLeft, foundIndexes.length, finishRound]);\n\n  const startRound = useCallback((listId: string, durationSec: number) => {\n    const found = QUIZ_LISTS.find((l) => l.id === listId) || XI_MATCHES.find((l) => l.id === listId);\n    if (!found) return;\n    setList(found);\n    setFoundIndexes([]);\n    setLastReward(0);\n    durationRef.current = durationSec;\n    setTimeLeft(durationSec);\n    setStatus('playing');\n  }, []);\n\n  const endRoundEarly = useCallback(() => {\n    if (status !== 'playing') return;\n    finishRound(foundIndexes.length);\n  }, [status, foundIndexes.length, finishRound]);\n\n  const submitGuess = useCallback(\n    (raw: string): { error: string | null } => {\n      if (!list || status !== 'playing') return { error: null };\n      const input = norm(raw);\n      if (!input) return { error: null };\n\n      const baseCounts = new Map<string, number>();\n      list.players.forEach((p) => {\n        const b = norm(playerBase(p));\n        baseCounts.set(b, (baseCounts.get(b) || 0) + 1);\n      });\n\n      const idx = list.players.findIndex((p, i) => {\n        if (foundIndexes.includes(i)) return false;\n        const full = norm(playerFull(p));\n        const base = norm(playerBase(p));\n        if (input === full) return true;\n        if (input === base && (baseCounts.get(base) || 0) === 1) return true;\n        // XI Type entries store just the surname as full/base (e.g.\n        // \"Donnarumma\"), with the real first+last name in `photo` — but the\n        // autocomplete suggestions pull from the global player database,\n        // which shows/inserts the full \"Gianluigi Donnarumma\" form. Typing\n        // or tapping that suggestion could never validate without this:\n        // only the bare surname ever worked.\n        const photo = playerPhoto(p);\n        if (photo && input === norm(photo)) return true;\n        return false;\n      });\n\n      if (idx === -1) return { error: 'not_found' };\n\n      const nextFound = [...foundIndexes, idx];\n      setFoundIndexes(nextFound);\n      fx.correct();\n\n      if (nextFound.length === list.players.length) {\n        finishRound(nextFound.length);\n      }\n\n      return { error: null };\n    },\n    [list, status, foundIndexes, finishRound]\n  );\n\n  return {\n    list,\n    status,\n    timeLeft,\n    duration: durationRef.current,\n    foundIndexes,\n    foundCount: foundIndexes.length,\n    totalCount: list?.players.length || 0,\n    startRound,\n    submitGuess,\n    endRoundEarly,\n    rewardsExhausted,\n    rewardedToday,\n    rewardedLimit: REWARDED_PER_DAY,\n    lastReward,\n  };\n}\n");
write("src/screens/GroupGameScreen.tsx", "// Shared screen for Groupe (up to 4 invites) and Duel (1 invite) race modes,\n// across \"Devine le joueur\" (main), \"Devine le club\" (club), \"Mode Liste\"\n// (liste), and \"Grille\" (grille) — see useGroupGame for the lobby/sync/\n// reward model this sits on top of. Grille also keeps its separate\n// turn-based 1v1 DuelScreen, unrelated to this one.\nimport React, { useEffect, useRef, useState } from 'react';\nimport { ActivityIndicator, Image, Modal, Pressable, ScrollView, Text, View } from 'react-native';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { useTheme } from '../theme/ThemeContext';\nimport { useI18n } from '../i18n/i18n';\nimport { useAuth } from '../state/auth';\nimport { useFriends } from '../state/friends';\nimport { GroupGameType, useGroupGame } from '../game/useGroupGame';\nimport { useInterstitialAd } from '../game/useInterstitialAd';\nimport { PLAYERS } from '../data/players';\nimport { Level, clubColor, clubInit, matchesGuess, stripAcc } from '../game/engine';\nimport { MAX_GUESSES, ClubGuessRow, compareClubGuess, resolveClubGuess } from '../game/useClubGuess';\nimport { matchesCriteria, criterionLabel } from '../game/gridDuel';\nimport { CLUB_DATA } from '../data/clubData';\nimport { QUIZ_LISTS, QuizDifficulty, playerFull, playerBase, playerPhoto } from '../data/quizLists';\nimport { XI_MATCHES } from '../data/xiMatches';\nimport { flagEmoji } from '../lib/flags';\nimport { getClubLogo } from '../lib/wikiLookup';\nimport ClubShield from '../components/ClubShield';\nimport RevealCard from '../components/RevealCard';\nimport HardShadowBox from '../components/HardShadowBox';\nimport PlayerPortrait from '../components/PlayerPortrait';\nimport XIPitch from '../components/XIPitch';\nimport RulesModal from '../components/RulesModal';\nimport { useRulesModal } from '../lib/useRulesModal';\nimport { KEY_ROWS_BY_LANG } from '../lib/keyboard';\nimport { logEvent } from '../lib/analytics';\n\nconst DURATIONS = [60, 90, 120, 180];\nconst LEVEL_META: Record<Level, { icon: string; labelKey: string }> = {\n  easy: { icon: '🟢', labelKey: 'quiz_difficulty_easy' },\n  medium: { icon: '🟡', labelKey: 'quiz_difficulty_medium' },\n  hard: { icon: '🔴', labelKey: 'quiz_difficulty_hard' },\n};\nconst CREST_SIZE = 96;\n\ninterface GroupGameScreenProps {\n  onBack?: () => void;\n  gameType: GroupGameType;\n  variant: 'duel' | 'group';\n  // 'xi' reuses gameType='liste' end to end (same DB game_type, same race\n  // mechanic) but points the creator's list picker at XI_MATCHES (\"XI Type\")\n  // instead of QUIZ_LISTS (\"Mode Liste\") — no schema change needed since the\n  // list content itself is client-side data either way.\n  listPool?: 'liste' | 'xi';\n  // Set when arriving from FriendsScreen's \"challenge\" picker: pre-selects\n  // that friend in the lobby instead of making the challenger pick them\n  // again from the full friends list they were just looking at.\n  inviteUserId?: string;\n  inviteUserName?: string;\n  onInviteConsumed?: () => void;\n}\n\nfunction Crest({ name, revealFraction }: { name: string; revealFraction: number }) {\n  const { colors, fonts } = useTheme();\n  const [url, setUrl] = useState<string | null>(null);\n  useEffect(() => {\n    let cancelled = false;\n    setUrl(null);\n    getClubLogo(name).then((u) => {\n      if (!cancelled) setUrl(u);\n    });\n    return () => {\n      cancelled = true;\n    };\n  }, [name]);\n  if (!url) {\n    return (\n      <View style={{ width: CREST_SIZE, height: CREST_SIZE, borderRadius: 18, backgroundColor: clubColor(name), alignItems: 'center', justifyContent: 'center' }}>\n        <Text style={{ fontFamily: fonts.display, fontSize: 30, color: '#fff' }}>{clubInit(name)}</Text>\n      </View>\n    );\n  }\n  const revealedWidth = Math.max(14, CREST_SIZE * revealFraction);\n  return (\n    <View style={{ width: CREST_SIZE, height: CREST_SIZE, borderRadius: 18, backgroundColor: colors.card, borderWidth: 2.5, borderColor: colors.border, overflow: 'hidden', alignItems: 'center', justifyContent: 'center' }}>\n      <View style={{ width: revealedWidth, height: CREST_SIZE, overflow: 'hidden' }}>\n        <Image source={{ uri: url }} style={{ width: CREST_SIZE, height: CREST_SIZE, transform: [{ scaleX: revealFraction >= 1 ? 1 : -1 }] }} resizeMode=\"contain\" />\n      </View>\n    </View>\n  );\n}\n\nfunction Chip({ icon, value, match, label }: { icon: string; value: string; match: boolean | null; label: string }) {\n  const { colors, accent, fonts } = useTheme();\n  const bg = match === true ? accent.mint : colors.card;\n  return (\n    <View style={{ alignItems: 'center', gap: 2, flex: 1 }}>\n      <View style={{ width: 44, height: 44, borderRadius: 999, backgroundColor: bg, borderWidth: 2, borderColor: colors.border, alignItems: 'center', justifyContent: 'center' }}>\n        <Text style={{ fontSize: 13 }}>{icon}</Text>\n        <Text style={{ fontFamily: fonts.displayBold, fontSize: 8, color: colors.ink }} numberOfLines={1}>{value}</Text>\n      </View>\n      <Text style={{ fontFamily: fonts.mono, fontSize: 7, color: colors.muted, letterSpacing: 0.5 }}>{label}</Text>\n    </View>\n  );\n}\n\nfunction ClubGuessChips({ row }: { row: ClubGuessRow }) {\n  const { t } = useI18n();\n  const { fonts, colors } = useTheme();\n  const compareIcon = (c: 'match' | 'up' | 'down') => (c === 'match' ? '✓' : c === 'up' ? '↑' : '↓');\n  return (\n    <View style={{ marginBottom: 8 }}>\n      <Text style={{ fontFamily: fonts.displayBold, fontSize: 12, color: colors.ink, marginBottom: 4, textAlign: 'center' }}>{row.name}</Text>\n      <View style={{ flexDirection: 'row', gap: 3 }}>\n        <Chip icon={flagEmoji(row.nat)} value={row.nat} match={row.natMatch} label={t('club_chip_nat')} />\n        <Chip icon={compareIcon(row.foundedCompare)} value={String(row.founded)} match={row.foundedCompare === 'match'} label={t('club_chip_est')} />\n        <Chip icon={compareIcon(row.capacityCompare)} value={`${Math.round(row.capacity / 1000)}k`} match={row.capacityCompare === 'match'} label={t('club_chip_cap')} />\n        <Chip icon={row.direction} value=\"\" match={null} label={t('club_chip_dir')} />\n        <Chip icon=\"📍\" value={`${row.distanceKm}`} match={row.distanceKm === 0} label={t('club_chip_dist')} />\n      </View>\n    </View>\n  );\n}\n\nexport default function GroupGameScreen({\n  onBack,\n  gameType,\n  variant,\n  listPool = 'liste',\n  inviteUserId,\n  inviteUserName,\n  onInviteConsumed,\n}: GroupGameScreenProps) {\n  const { colors, accent, fonts } = useTheme();\n  const { t, lang } = useI18n();\n  const insets = useSafeAreaInsets();\n  const rules = useRulesModal(listPool === 'xi' ? 'group_xi' : variant === 'duel' ? `duel_${gameType}` : 'group');\n  const { user } = useAuth();\n  const { friends, loading: friendsLoading } = useFriends();\n  const {\n    game,\n    players,\n    loading,\n    mysteryPlayer,\n    mysteryClub,\n    mysteryList,\n    grid,\n    isCreator,\n    createGroup,\n    respondInvite,\n    cancelLobby,\n    startRound,\n    submitResult,\n    finishGame,\n    leaveFinished,\n    lastReward,\n  } = useGroupGame();\n  const { recordRoundPlayed } = useInterstitialAd();\n\n  const maxFriends = variant === 'duel' ? 1 : 4;\n  const [selectedFriendIds, setSelectedFriendIds] = useState<string[]>([]);\n  const [roundSeconds, setRoundSeconds] = useState(90);\n  const [level, setLevel] = useState<Level>('medium');\n  const [listDifficulty, setListDifficulty] = useState<QuizDifficulty>('easy');\n  const [busy, setBusy] = useState(false);\n  const [createError, setCreateError] = useState<string | null>(null);\n  const autoInviteFiredRef = useRef(false);\n\n  // Arrived via FriendsScreen's \"challenge\" picker with a friend already\n  // chosen: pre-select them (there's only ever one slot in a duel lobby)\n  // instead of making the challenger find them again in the list below.\n  useEffect(() => {\n    if (!inviteUserId || loading || game) return;\n    setSelectedFriendIds([inviteUserId]);\n    onInviteConsumed?.();\n  }, [inviteUserId, loading, game, onInviteConsumed]);\n\n  // A 1-on-1 challenge from FriendsScreen shouldn't need a \"create the\n  // room\" tap like the up-to-4 Groupe flow does — send the invite the\n  // moment we land here, same as DuelScreen/XIDuelScreen already do for\n  // Grille/XI Type challenges.\n  useEffect(() => {\n    if (variant !== 'duel' || !inviteUserId || loading || game || autoInviteFiredRef.current) return;\n    autoInviteFiredRef.current = true;\n    setCreateError(null);\n    createGroup([inviteUserId], [inviteUserName || ''], roundSeconds, gameType).then(({ error }) => {\n      // Only ever a raw internal slug or a raw Supabase error string,\n      // neither meant for display — always the generic translated message.\n      if (error) setCreateError(t('error_generic'));\n    });\n  }, [variant, inviteUserId, inviteUserName, loading, game, roundSeconds, gameType, createGroup]);\n\n  // Local per-round play state — only reported back via submitResult() at\n  // solve or timeout, so other players never see live guesses, just the\n  // eventual result. Only the fields relevant to `gameType` get used.\n  const [answer, setAnswer] = useState('');\n  const [wrongList, setWrongList] = useState<string[]>([]);\n  const [revealed, setRevealed] = useState(0);\n  const [clubGuesses, setClubGuesses] = useState<ClubGuessRow[]>([]);\n  const [foundIndexes, setFoundIndexes] = useState<number[]>([]);\n  const [grilleCells, setGrilleCells] = useState<(string | null)[]>(Array(9).fill(null));\n  const [grilleUsedPlayers, setGrilleUsedPlayers] = useState<string[]>([]);\n  const [grilleSelectedCell, setGrilleSelectedCell] = useState<number | null>(null);\n  const [error, setError] = useState<string | null>(null);\n  const [solved, setSolved] = useState(false);\n  // Distinct from `solved`: club can run out of its 6 guesses without ever\n  // finding the mystery club — that player is done playing too (same\n  // \"waiting for the round to end\" screen), but it isn't a win, so it needs\n  // its own flag rather than overloading `solved` and showing \"Found it!\".\n  const [outOfAttempts, setOutOfAttempts] = useState(false);\n  const [now, setNow] = useState(Date.now());\n  const handledRoundRef = useRef<string | null>(null);\n\n  const myRow = game ? players.find((p) => p.user_id === user?.id) : undefined;\n\n  // Diagnostic for the \"invitee sees a create-room screen instead of\n  // accept/decline\" report — logs exactly what state this screen landed in\n  // once loading settles, so the real cause (stale invite picked up by\n  // loadActive(), a myRow lookup miss, an unexpected game.status, etc.) is\n  // visible in app_events instead of guessed at from database archaeology.\n  // Fires once per distinct game.id (or once for \"no game at all\").\n  const loggedStateForRef = useRef<string | null>(null);\n  useEffect(() => {\n    if (loading || !user) return;\n    const key = `${variant}:${gameType}:${game?.id ?? 'none'}`;\n    if (loggedStateForRef.current === key) return;\n    loggedStateForRef.current = key;\n    logEvent(user.id, 'group_screen_diagnostic', {\n      variant,\n      gameType,\n      hasInviteUserId: !!inviteUserId,\n      gameId: game?.id ?? null,\n      gameStatus: game?.status ?? null,\n      gameCreatorId: game?.creator_id ?? null,\n      myUserId: user.id,\n      myRowStatus: myRow?.status ?? null,\n      isCreator,\n      playersCount: players.length,\n    });\n  }, [loading, user, variant, gameType, inviteUserId, game, myRow, isCreator, players.length]);\n\n  useEffect(() => {\n    if (game && game.status === 'active' && handledRoundRef.current !== game.id) {\n      setAnswer('');\n      setWrongList([]);\n      setClubGuesses([]);\n      setFoundIndexes([]);\n      setGrilleCells(Array(9).fill(null));\n      setGrilleUsedPlayers([]);\n      setGrilleSelectedCell(null);\n      setError(null);\n      setSolved(false);\n      setOutOfAttempts(false);\n      if (gameType === 'main' && mysteryPlayer) setRevealed(Math.max(1, Math.min(3, mysteryPlayer.clubs.length - 2)));\n    }\n  }, [game?.id, game?.status, mysteryPlayer, gameType]);\n\n  useEffect(() => {\n    if (!game || game.status !== 'active') return;\n    const id = setInterval(() => setNow(Date.now()), 1000);\n    return () => clearInterval(id);\n  }, [game?.status, game?.id]);\n\n  const secondsLeft =\n    game && game.status === 'active' && game.started_at\n      ? Math.max(0, game.round_seconds - Math.floor((now - new Date(game.started_at).getTime()) / 1000))\n      : 0;\n\n  // Whoever's local countdown hits zero first reports (if not already\n  // solved) and flips the shared row — see useGroupGame.finishGame for the\n  // guard that makes a near-simultaneous second call harmless.\n  useEffect(() => {\n    if (!game || game.status !== 'active') return;\n    if (secondsLeft > 0) return;\n    if (handledRoundRef.current === game.id) return;\n    handledRoundRef.current = game.id;\n    if (!solved && !outOfAttempts) {\n      if (gameType === 'liste') submitResult({ foundCount: foundIndexes.length, solved: false });\n      else if (gameType === 'grille') submitResult({ foundCount: grilleCells.filter((c) => c).length, solved: false });\n      else submitResult({ attempts: gameType === 'club' ? clubGuesses.length : wrongList.length, elapsedMs: null, solved: false });\n    }\n    finishGame();\n  }, [\n    secondsLeft,\n    game?.id,\n    game?.status,\n    solved,\n    outOfAttempts,\n    gameType,\n    wrongList.length,\n    clubGuesses.length,\n    foundIndexes.length,\n    grilleCells,\n    submitResult,\n    finishGame,\n  ]);\n\n  const toggleFriend = (id: string) => {\n    setSelectedFriendIds((prev) => {\n      if (prev.includes(id)) return prev.filter((x) => x !== id);\n      if (maxFriends === 1) return [id];\n      return prev.length < maxFriends ? [...prev, id] : prev;\n    });\n  };\n\n  const handleCreate = async () => {\n    if (!selectedFriendIds.length || busy) return;\n    setBusy(true);\n    setCreateError(null);\n    const names = selectedFriendIds.map((id) => friends.find((f) => f.id === id)?.display_name || '');\n    const { error } = await createGroup(selectedFriendIds, names, roundSeconds, gameType);\n    if (error) setCreateError(t('error_generic'));\n    setBusy(false);\n  };\n\n  const handleStartMain = async () => {\n    if (busy) return;\n    setBusy(true);\n    await startRound({ level });\n    setBusy(false);\n  };\n  const handleStartClub = async () => {\n    if (busy) return;\n    setBusy(true);\n    await startRound();\n    setBusy(false);\n  };\n  const handleStartListe = async (listId: string) => {\n    if (busy) return;\n    setBusy(true);\n    await startRound({ listId });\n    setBusy(false);\n  };\n  const handleStartGrille = async () => {\n    if (busy) return;\n    setBusy(true);\n    await startRound();\n    setBusy(false);\n  };\n\n  const submitMainGuess = () => {\n    if (!mysteryPlayer || solved || !game || game.status !== 'active' || !answer.trim()) return;\n    if (matchesGuess(mysteryPlayer, answer)) {\n      const attempt = wrongList.length + 1;\n      const elapsed = game.started_at ? Date.now() - new Date(game.started_at).getTime() : null;\n      setSolved(true);\n      setRevealed(mysteryPlayer.clubs.length);\n      setAnswer('');\n      submitResult({ attempts: attempt, elapsedMs: elapsed, solved: true });\n    } else {\n      setWrongList((prev) => [...prev, answer.trim()]);\n      setRevealed((prev) => Math.min(prev + 1, mysteryPlayer.clubs.length));\n      setAnswer('');\n    }\n  };\n\n  const submitClubGuess = () => {\n    if (!mysteryClub || solved || outOfAttempts || !game || game.status !== 'active' || !answer.trim()) return;\n    const name = resolveClubGuess(answer);\n    if (!name) {\n      setError(t('club_error_unknown'));\n      return;\n    }\n    if (clubGuesses.some((g) => g.name === name)) {\n      setError(t('club_error_used'));\n      return;\n    }\n    const row = compareClubGuess(name, mysteryClub);\n    if (!row) {\n      setError(t('club_error_unknown'));\n      return;\n    }\n    const nextGuesses = [row, ...clubGuesses];\n    setClubGuesses(nextGuesses);\n    setAnswer('');\n    setError(null);\n    const won = name === mysteryClub;\n    if (won) {\n      const elapsed = game.started_at ? Date.now() - new Date(game.started_at).getTime() : null;\n      setSolved(true);\n      submitResult({ attempts: nextGuesses.length, elapsedMs: elapsed, solved: true });\n    } else if (nextGuesses.length >= MAX_GUESSES) {\n      setOutOfAttempts(true);\n      submitResult({ attempts: nextGuesses.length, elapsedMs: null, solved: false });\n    }\n  };\n\n  // Letters only: the on-screen keyboard has no hyphen/apostrophe keys, but\n  // real surnames do (\"Alexander-Arnold\", \"Guivarc'h\") — without this, those\n  // players could never be typed correctly no matter what's entered.\n  const normListeName = (s: string) => stripAcc(s.toLowerCase()).replace(/[^a-z]/g, '');\n\n  const submitListeGuess = () => {\n    if (!mysteryList || solved || !game || game.status !== 'active' || !answer.trim()) return;\n    const input = normListeName(answer.trim());\n    const baseCounts = new Map<string, number>();\n    mysteryList.players.forEach((p) => {\n      const b = normListeName(playerBase(p));\n      baseCounts.set(b, (baseCounts.get(b) || 0) + 1);\n    });\n    const idx = mysteryList.players.findIndex((p, i) => {\n      if (foundIndexes.includes(i)) return false;\n      const full = normListeName(playerFull(p));\n      const base = normListeName(playerBase(p));\n      if (input === full) return true;\n      if (input === base && (baseCounts.get(base) || 0) === 1) return true;\n      return false;\n    });\n    if (idx === -1) {\n      setError(t('club_error_unknown'));\n      return;\n    }\n    const nextFound = [...foundIndexes, idx];\n    setFoundIndexes(nextFound);\n    setAnswer('');\n    setError(null);\n    if (nextFound.length === mysteryList.players.length) {\n      setSolved(true);\n      submitResult({ foundCount: nextFound.length, solved: true });\n    }\n  };\n\n  // Grille uses a tap-a-cell-then-type modal (like SoloGridScreen) rather\n  // than the single shared answer bar the other three games use, so it gets\n  // its own submit function called from that modal instead of submitGuess().\n  const submitGrilleCell = () => {\n    if (!grid || grilleSelectedCell === null || !game || game.status !== 'active' || !answer.trim()) return;\n    const ri = Math.floor(grilleSelectedCell / 3);\n    const ci = grilleSelectedCell % 3;\n    const rowC = grid.rows[ri];\n    const colC = grid.cols[ci];\n    const found = matchesCriteria(answer, rowC, colC);\n    if (!found) {\n      setError(t('duel_error_invalid'));\n      return;\n    }\n    if (grilleUsedPlayers.includes(found.n)) {\n      setError(t('duel_error_used'));\n      return;\n    }\n    const nextCells = grilleCells.slice();\n    nextCells[grilleSelectedCell] = found.n;\n    setGrilleCells(nextCells);\n    setGrilleUsedPlayers((prev) => [...prev, found.n]);\n    setGrilleSelectedCell(null);\n    setAnswer('');\n    setError(null);\n    const filled = nextCells.filter((c) => c).length;\n    if (filled === 9) {\n      const elapsed = game.started_at ? Date.now() - new Date(game.started_at).getTime() : null;\n      setSolved(true);\n      submitResult({ foundCount: 9, elapsedMs: elapsed, solved: true });\n    }\n  };\n\n  const submitGuess = () => {\n    if (gameType === 'main') submitMainGuess();\n    else if (gameType === 'club') submitClubGuess();\n    else submitListeGuess();\n  };\n\n  const withBack = (node: React.ReactElement, opts?: { hideBack?: boolean }) => (\n    <View style={{ flex: 1 }}>\n      {node}\n      {onBack && !opts?.hideBack && (\n        <Pressable\n          onPress={onBack}\n          hitSlop={8}\n          style={{ position: 'absolute', top: insets.top + 14, left: 20, width: 30, height: 30, borderRadius: 999, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, alignItems: 'center', justifyContent: 'center' }}\n        >\n          <Text style={{ fontFamily: fonts.display, fontSize: 14, color: colors.ink }}>←</Text>\n        </Pressable>\n      )}\n      <Pressable\n        onPress={rules.show}\n        hitSlop={8}\n        style={{ position: 'absolute', top: insets.top + 14, right: 20, width: 30, height: 30, borderRadius: 999, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, alignItems: 'center', justifyContent: 'center' }}\n      >\n        <Text style={{ fontFamily: fonts.displayBold, fontSize: 13, color: colors.ink }}>?</Text>\n      </Pressable>\n      <RulesModal visible={rules.visible} onClose={rules.hide} title={t('rules_group_title')} body={t('rules_group_body')} />\n    </View>\n  );\n\n  if (loading) {\n    return withBack(\n      <View style={{ flex: 1, backgroundColor: colors.bg, alignItems: 'center', justifyContent: 'center' }}>\n        <ActivityIndicator color={colors.ink} />\n      </View>\n    );\n  }\n\n  // No active game yet. For a 1-on-1 challenge the invite fires\n  // automatically above — this just covers the brief send, or a failure.\n  if (!game && variant === 'duel' && inviteUserId) {\n    return withBack(\n      <View style={{ flex: 1, backgroundColor: colors.bg, alignItems: 'center', justifyContent: 'center', gap: 14, paddingHorizontal: 20 }}>\n        {createError ? (\n          <>\n            <Text style={{ fontSize: 40 }}>😕</Text>\n            <Text style={{ fontFamily: fonts.display, fontSize: 15, color: colors.ink, textAlign: 'center' }}>{t('duel_invite_error')}</Text>\n            <Pressable\n              onPress={() => {\n                setCreateError(null);\n                autoInviteFiredRef.current = false;\n              }}\n              style={{ paddingVertical: 12, paddingHorizontal: 20, backgroundColor: accent.coral, borderWidth: 2, borderColor: colors.border, borderRadius: 12 }}\n            >\n              <Text style={{ fontFamily: fonts.display, fontSize: 13, color: '#fff' }}>{t('group_retry')}</Text>\n            </Pressable>\n          </>\n        ) : (\n          <ActivityIndicator color={colors.ink} />\n        )}\n      </View>\n    );\n  }\n\n  // No active game, 1-on-1, arrived directly from the Jeux hub (not via\n  // FriendsScreen's \"Défier\" button, which already auto-invites above via\n  // inviteUserId): tapping a friend fires the challenge immediately,\n  // skipping the multi-step \"create a room\" flow below (duration picker +\n  // separate \"create\" tap) that variant==='group' still needs — matching\n  // the same one-tap feel Grille/XI Type's own duel screens already have.\n  if (!game && variant === 'duel') {\n    const challenge = async (id: string, name: string) => {\n      if (busy) return;\n      setBusy(true);\n      setCreateError(null);\n      const { error } = await createGroup([id], [name], roundSeconds, gameType);\n      if (error) setCreateError(t('error_generic'));\n      setBusy(false);\n    };\n    return withBack(\n      <View style={{ flex: 1, backgroundColor: colors.bg, paddingTop: insets.top + 60, paddingHorizontal: 20 }}>\n        <Text style={{ fontFamily: fonts.display, fontSize: 22, color: colors.ink }}>{t('duel_create')}</Text>\n        <Text style={{ fontFamily: fonts.body, fontSize: 12, color: colors.muted, marginTop: 4 }}>{t('duel_challenge_pick_sub')}</Text>\n        {createError && (\n          <Text style={{ fontFamily: fonts.body, fontSize: 12, color: colors.muted, marginTop: 12, textAlign: 'center' }}>{createError}</Text>\n        )}\n        {!friends.length && !friendsLoading ? (\n          <Text style={{ fontFamily: fonts.body, fontSize: 13, color: colors.muted, marginTop: 24 }}>{t('group_no_friends')}</Text>\n        ) : (\n          <ScrollView style={{ marginTop: 20, maxHeight: 420 }}>\n            {friends.map((f) => (\n              <Pressable\n                key={f.id}\n                disabled={busy}\n                onPress={() => challenge(f.id, f.display_name)}\n                style={{\n                  flexDirection: 'row', alignItems: 'center', gap: 10, paddingVertical: 12, paddingHorizontal: 12,\n                  backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12, marginBottom: 6, opacity: busy ? 0.6 : 1,\n                }}\n              >\n                <Text style={{ fontFamily: fonts.displayBold, fontSize: 13, color: colors.ink, flex: 1 }}>{f.display_name}</Text>\n                {busy ? <ActivityIndicator size=\"small\" color={colors.ink} /> : <Text style={{ fontSize: 16 }}>⚔️</Text>}\n              </Pressable>\n            ))}\n            {!friends.length && friendsLoading && <ActivityIndicator color={colors.ink} style={{ marginTop: 10 }} />}\n          </ScrollView>\n        )}\n      </View>\n    );\n  }\n\n  // No active game: create a lobby (Groupe, up to 4 friends).\n  if (!game) {\n    return withBack(\n      <View style={{ flex: 1, backgroundColor: colors.bg, paddingTop: insets.top + 60, paddingHorizontal: 20 }}>\n        <Text style={{ fontFamily: fonts.display, fontSize: 22, color: colors.ink }}>{t('group_create_title')}</Text>\n        <Text style={{ fontFamily: fonts.body, fontSize: 12, color: colors.muted, marginTop: 4 }}>{t('group_create_sub')}</Text>\n\n        {!friends.length && !friendsLoading ? (\n          <Text style={{ fontFamily: fonts.body, fontSize: 13, color: colors.muted, marginTop: 24 }}>{t('group_no_friends')}</Text>\n        ) : (\n          <>\n            <Text style={{ fontFamily: fonts.mono, fontSize: 10, color: colors.muted, letterSpacing: 1, marginTop: 20 }}>\n              {t('group_pick_friends')} ({selectedFriendIds.length}/{maxFriends})\n            </Text>\n            <ScrollView style={{ marginTop: 8, maxHeight: 260 }}>\n              {friends.map((f) => {\n                const checked = selectedFriendIds.includes(f.id);\n                return (\n                  <Pressable\n                    key={f.id}\n                    onPress={() => toggleFriend(f.id)}\n                    style={{ flexDirection: 'row', alignItems: 'center', gap: 10, paddingVertical: 10, paddingHorizontal: 12, backgroundColor: checked ? accent.mint : colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12, marginBottom: 6 }}\n                  >\n                    <Text style={{ fontFamily: fonts.displayBold, fontSize: 13, color: colors.ink, flex: 1 }}>{f.display_name}</Text>\n                    <Text style={{ fontFamily: fonts.display, fontSize: 13 }}>{checked ? '✓' : ''}</Text>\n                  </Pressable>\n                );\n              })}\n              {!friends.length && friendsLoading && <ActivityIndicator color={colors.ink} style={{ marginTop: 10 }} />}\n            </ScrollView>\n\n            <Text style={{ fontFamily: fonts.mono, fontSize: 10, color: colors.muted, letterSpacing: 1, marginTop: 16 }}>{t('group_pick_duration')}</Text>\n            <View style={{ flexDirection: 'row', gap: 8, marginTop: 8 }}>\n              {DURATIONS.map((d) => (\n                <Pressable\n                  key={d}\n                  onPress={() => setRoundSeconds(d)}\n                  style={{ flex: 1, paddingVertical: 12, backgroundColor: roundSeconds === d ? accent.coral : colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12, alignItems: 'center' }}\n                >\n                  <Text style={{ fontFamily: fonts.display, fontSize: 13, color: roundSeconds === d ? '#fff' : colors.ink }}>{d}s</Text>\n                </Pressable>\n              ))}\n            </View>\n\n            <Pressable\n              onPress={handleCreate}\n              disabled={!selectedFriendIds.length || busy}\n              style={{ marginTop: 20, paddingVertical: 14, backgroundColor: accent.coral, borderWidth: 2, borderColor: colors.border, borderRadius: 14, alignItems: 'center', opacity: selectedFriendIds.length ? 1 : 0.5 }}\n            >\n              <Text style={{ fontFamily: fonts.display, fontSize: 13, color: '#fff', letterSpacing: 0.5, textTransform: 'uppercase' }}>{t('group_create_button')}</Text>\n            </Pressable>\n          </>\n        )}\n      </View>\n    );\n  }\n\n  // Invited, haven't responded yet.\n  if (game.status === 'lobby' && myRow?.status === 'invited') {\n    const creatorRow = players.find((p) => p.user_id === game.creator_id);\n    return withBack(\n      <View style={{ flex: 1, backgroundColor: colors.bg, paddingTop: insets.top + 14, paddingHorizontal: 20, alignItems: 'center', justifyContent: 'center', gap: 16 }}>\n        <Text style={{ fontSize: 40 }}>👥</Text>\n        <Text style={{ fontFamily: fonts.display, fontSize: 20, color: colors.ink, textAlign: 'center' }}>\n          {(creatorRow?.display_name || '') + ' ' + t('group_invite_title')}\n        </Text>\n        <Text style={{ fontFamily: fonts.body, fontSize: 12, color: colors.muted }}>{game.round_seconds}s · {t('group_invite_sub')}</Text>\n        <View style={{ flexDirection: 'row', gap: 10, marginTop: 8 }}>\n          <Pressable onPress={() => respondInvite(false)} style={{ paddingVertical: 12, paddingHorizontal: 20, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12 }}>\n            <Text style={{ fontFamily: fonts.display, fontSize: 13, color: colors.ink }}>{t('duel_invite_decline')}</Text>\n          </Pressable>\n          <Pressable onPress={() => respondInvite(true)} style={{ paddingVertical: 12, paddingHorizontal: 20, backgroundColor: accent.mint, borderWidth: 2, borderColor: colors.border, borderRadius: 12 }}>\n            <Text style={{ fontFamily: fonts.display, fontSize: 13, color: colors.ink }}>{t('duel_invite_accept')}</Text>\n          </Pressable>\n        </View>\n      </View>\n    );\n  }\n\n  // Lobby: waiting room (Groupe), or a classic direct-duel wait (Duel — no\n  // room/code, just \"waiting for them to answer\" like Grille/XI Type).\n  if (game.status === 'lobby') {\n    const joinedCount = players.filter((p) => p.status === 'joined').length;\n    const listsForDifficulty = listPool === 'xi' ? XI_MATCHES : QUIZ_LISTS.filter((l) => l.difficulty === listDifficulty);\n    const opponentRow = variant === 'duel' ? players.find((p) => p.user_id !== user?.id) : null;\n    return withBack(\n      <View style={{ flex: 1, backgroundColor: colors.bg, paddingTop: insets.top + 60, paddingHorizontal: 20 }}>\n        <ScrollView>\n          {variant === 'duel' ? (\n            <Text style={{ fontFamily: fonts.display, fontSize: 20, color: colors.ink }}>\n              {opponentRow?.status === 'declined'\n                ? t('duel_invite_declined_title').replace('{name}', opponentRow.display_name || '')\n                : opponentRow?.status === 'joined'\n                ? (opponentRow.display_name || '') + ' ' + t('duel_opponent_ready_suffix')\n                : t('duel_invite_waiting_title').replace('{name}', opponentRow?.display_name || '')}\n            </Text>\n          ) : (\n            <>\n              <Text style={{ fontFamily: fonts.display, fontSize: 20, color: colors.ink }}>\n                {t('group_lobby_title')} {joinedCount}/{players.length}\n              </Text>\n              <View style={{ marginTop: 16, gap: 8 }}>\n                {players.map((p) => (\n                  <View key={p.id} style={{ flexDirection: 'row', alignItems: 'center', gap: 10, paddingVertical: 10, paddingHorizontal: 12, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12 }}>\n                    <Text style={{ fontSize: 16 }}>{p.status === 'joined' ? '✓' : p.status === 'declined' ? '✕' : '○'}</Text>\n                    <Text style={{ fontFamily: fonts.displayBold, fontSize: 13, color: colors.ink, flex: 1 }}>{p.display_name}</Text>\n                    <Text style={{ fontFamily: fonts.mono, fontSize: 9, color: colors.muted }}>\n                      {p.status === 'joined' ? t('group_status_joined') : p.status === 'declined' ? t('group_status_declined') : t('group_status_waiting')}\n                    </Text>\n                  </View>\n                ))}\n              </View>\n            </>\n          )}\n\n          {isCreator && gameType === 'main' && (\n            <>\n              <Text style={{ fontFamily: fonts.mono, fontSize: 10, color: colors.muted, letterSpacing: 1, marginTop: 20 }}>{t('group_pick_level')}</Text>\n              <View style={{ flexDirection: 'row', gap: 8, marginTop: 8 }}>\n                {(Object.keys(LEVEL_META) as Level[]).map((l) => (\n                  <Pressable\n                    key={l}\n                    onPress={() => setLevel(l)}\n                    style={{ flex: 1, paddingVertical: 12, backgroundColor: level === l ? accent.coral : colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12, alignItems: 'center' }}\n                  >\n                    <Text style={{ fontFamily: fonts.display, fontSize: 12, color: level === l ? '#fff' : colors.ink }}>{LEVEL_META[l].icon} {t(LEVEL_META[l].labelKey)}</Text>\n                  </Pressable>\n                ))}\n              </View>\n              <Pressable\n                onPress={handleStartMain}\n                disabled={joinedCount < 2 || busy}\n                style={{ marginTop: 20, paddingVertical: 14, backgroundColor: accent.coral, borderWidth: 2, borderColor: colors.border, borderRadius: 14, alignItems: 'center', opacity: joinedCount < 2 ? 0.5 : 1 }}\n              >\n                <Text style={{ fontFamily: fonts.display, fontSize: 13, color: '#fff', letterSpacing: 0.5, textTransform: 'uppercase' }}>\n                  {t('group_start_button')} {joinedCount}\n                </Text>\n              </Pressable>\n            </>\n          )}\n\n          {isCreator && gameType === 'club' && (\n            <Pressable\n              onPress={handleStartClub}\n              disabled={joinedCount < 2 || busy}\n              style={{ marginTop: 20, paddingVertical: 14, backgroundColor: accent.coral, borderWidth: 2, borderColor: colors.border, borderRadius: 14, alignItems: 'center', opacity: joinedCount < 2 ? 0.5 : 1 }}\n            >\n              <Text style={{ fontFamily: fonts.display, fontSize: 13, color: '#fff', letterSpacing: 0.5, textTransform: 'uppercase' }}>\n                {t('group_start_button')} {joinedCount}\n              </Text>\n            </Pressable>\n          )}\n\n          {isCreator && gameType === 'liste' && (\n            <>\n              {listPool !== 'xi' && (\n                <>\n                  <Text style={{ fontFamily: fonts.body, fontSize: 12, color: colors.muted, marginTop: 6 }}>{t('quiz_choose_difficulty')}</Text>\n                  <View style={{ flexDirection: 'row', gap: 8, marginTop: 8 }}>\n                    {(['easy', 'medium', 'hard'] as QuizDifficulty[]).map((d) => (\n                      <Pressable\n                        key={d}\n                        onPress={() => setListDifficulty(d)}\n                        style={{ flex: 1, paddingVertical: 12, backgroundColor: listDifficulty === d ? accent.coral : colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12, alignItems: 'center' }}\n                      >\n                        <Text style={{ fontFamily: fonts.display, fontSize: 12, color: listDifficulty === d ? '#fff' : colors.ink }}>{t(`quiz_difficulty_${d}`)}</Text>\n                      </Pressable>\n                    ))}\n                  </View>\n                </>\n              )}\n              <View style={{ marginTop: 10, gap: 8 }}>\n                {listsForDifficulty.map((l) => (\n                  <Pressable\n                    key={l.id}\n                    onPress={() => handleStartListe(l.id)}\n                    disabled={joinedCount < 2 || busy}\n                    style={{ paddingVertical: 12, paddingHorizontal: 14, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12, opacity: joinedCount < 2 ? 0.5 : 1 }}\n                  >\n                    <Text style={{ fontFamily: fonts.displayBold, fontSize: 13, color: colors.ink }}>{l.title}</Text>\n                  </Pressable>\n                ))}\n              </View>\n            </>\n          )}\n\n          {isCreator && gameType === 'grille' && (\n            <Pressable\n              onPress={handleStartGrille}\n              disabled={joinedCount < 2 || busy}\n              style={{ marginTop: 20, paddingVertical: 14, backgroundColor: accent.coral, borderWidth: 2, borderColor: colors.border, borderRadius: 14, alignItems: 'center', opacity: joinedCount < 2 ? 0.5 : 1 }}\n            >\n              <Text style={{ fontFamily: fonts.display, fontSize: 13, color: '#fff', letterSpacing: 0.5, textTransform: 'uppercase' }}>\n                {t('group_start_button')} {joinedCount}\n              </Text>\n            </Pressable>\n          )}\n        </ScrollView>\n\n        <Pressable onPress={() => cancelLobby()} style={{ paddingVertical: 12, alignItems: 'center' }}>\n          <Text style={{ fontFamily: fonts.mono, fontSize: 11, color: colors.muted }}>{t('group_cancel')}</Text>\n        </Pressable>\n      </View>\n    );\n  }\n\n  // Never responded to the invite before the creator started without us —\n  // no seat to play from, so just let them back out rather than falling\n  // into the active/results branches below as if we were racing too.\n  if (game.status !== 'lobby' && myRow?.status !== 'joined') {\n    return withBack(\n      <View style={{ flex: 1, backgroundColor: colors.bg, paddingTop: insets.top + 14, paddingHorizontal: 20, alignItems: 'center', justifyContent: 'center', gap: 12 }}>\n        <Text style={{ fontSize: 40 }}>👥</Text>\n        <Text style={{ fontFamily: fonts.display, fontSize: 16, color: colors.ink, textAlign: 'center' }}>{t('group_missed_title')}</Text>\n        <Pressable onPress={() => leaveFinished()} style={{ paddingVertical: 12, paddingHorizontal: 20, backgroundColor: accent.coral, borderWidth: 2, borderColor: colors.border, borderRadius: 12 }}>\n          <Text style={{ fontFamily: fonts.display, fontSize: 13, color: '#fff' }}>{t('group_leave')}</Text>\n        </Pressable>\n      </View>\n    );\n  }\n\n  // Active round.\n  if (game.status === 'active') {\n    const contentReady =\n      gameType === 'main' ? !!mysteryPlayer : gameType === 'club' ? !!mysteryClub : gameType === 'grille' ? !!grid : !!mysteryList;\n    if (!contentReady) {\n      return withBack(\n        <View style={{ flex: 1, backgroundColor: colors.bg, alignItems: 'center', justifyContent: 'center' }}>\n          <ActivityIndicator color={colors.ink} />\n        </View>\n      );\n    }\n    const others = players.filter((p) => p.status === 'joined' && p.user_id !== user?.id);\n\n    if (solved || outOfAttempts) {\n      return withBack(\n        <View style={{ flex: 1, backgroundColor: colors.bg, paddingTop: insets.top + 14, paddingHorizontal: 20, alignItems: 'center', justifyContent: 'center', gap: 14 }}>\n          <Text style={{ fontSize: 40 }}>{solved ? '✅' : '😔'}</Text>\n          <Text style={{ fontFamily: fonts.display, fontSize: 20, color: colors.ink }}>{solved ? t('group_solved_wait') : t('group_out_of_attempts_wait')}</Text>\n          <View style={{ paddingVertical: 6, paddingHorizontal: 14, backgroundColor: colors.track, borderRadius: 999 }}>\n            <Text style={{ fontFamily: fonts.mono, fontSize: 12, color: colors.muted }}>⏱ {secondsLeft}s</Text>\n          </View>\n          <View style={{ flexDirection: 'row', gap: 6, flexWrap: 'wrap', justifyContent: 'center' }}>\n            {others.map((p) => (\n              <View key={p.id} style={{ paddingVertical: 4, paddingHorizontal: 9, backgroundColor: colors.card, borderWidth: 1.5, borderColor: colors.border, borderRadius: 999 }}>\n                <Text style={{ fontFamily: fonts.mono, fontSize: 10, color: colors.ink }}>{p.solved ? '✅' : '⏳'} {p.display_name}</Text>\n              </View>\n            ))}\n          </View>\n        </View>,\n        { hideBack: true }\n      );\n    }\n\n    const timerBar = (\n      <>\n        <View style={{ paddingHorizontal: 20, flexDirection: 'row', justifyContent: 'center', alignItems: 'center' }}>\n          <View style={{ paddingVertical: 4, paddingHorizontal: 10, backgroundColor: secondsLeft <= 10 ? accent.wrongRed : colors.track, borderRadius: 999 }}>\n            <Text style={{ fontFamily: fonts.mono, fontSize: 12, color: secondsLeft <= 10 ? '#fff' : colors.muted }}>⏱ {secondsLeft}s</Text>\n          </View>\n        </View>\n        <View style={{ paddingHorizontal: 20, flexDirection: 'row', gap: 6, flexWrap: 'wrap', justifyContent: 'center', marginTop: 8 }}>\n          {others.map((p) => (\n            <View key={p.id} style={{ paddingVertical: 3, paddingHorizontal: 8, backgroundColor: colors.card, borderWidth: 1.5, borderColor: colors.border, borderRadius: 999 }}>\n              <Text style={{ fontFamily: fonts.mono, fontSize: 9, color: colors.ink }}>{p.solved ? '✅' : '⏳'} {p.display_name}</Text>\n            </View>\n          ))}\n        </View>\n      </>\n    );\n\n    const keyboard = (\n      <View style={{ marginTop: 8, gap: 4 }}>\n        {KEY_ROWS_BY_LANG[lang].map((row, ri) => (\n          <View key={ri} style={{ flexDirection: 'row', gap: 4 }}>\n            {ri === 2 && <View style={{ flex: 0.5 }} />}\n            {row.split('').map((l) => (\n              <Pressable\n                key={l}\n                onPress={() => setAnswer(answer + l)}\n                style={{ flex: 1, height: 36, borderRadius: 6, backgroundColor: colors.card, borderWidth: 1.5, borderColor: colors.border, alignItems: 'center', justifyContent: 'center' }}\n              >\n                <Text style={{ fontFamily: fonts.displayBold, fontSize: 11, color: colors.ink }}>{l}</Text>\n              </Pressable>\n            ))}\n            {ri === 2 && <View style={{ flex: 0.5 }} />}\n          </View>\n        ))}\n        <View style={{ flexDirection: 'row', gap: 4 }}>\n          <Pressable onPress={() => setAnswer(answer.slice(0, -1))} style={{ flex: 1.4, height: 36, borderRadius: 6, backgroundColor: colors.card, borderWidth: 1.5, borderColor: colors.border, alignItems: 'center', justifyContent: 'center' }}>\n            <Text style={{ fontFamily: fonts.displayBold, fontSize: 11, color: colors.ink }}>{t('game_backspace')}</Text>\n          </Pressable>\n          <Pressable onPress={() => setAnswer(answer + ' ')} style={{ flex: 3, height: 36, borderRadius: 6, backgroundColor: colors.card, borderWidth: 1.5, borderColor: colors.border, alignItems: 'center', justifyContent: 'center' }}>\n            <Text style={{ fontFamily: fonts.displayBold, fontSize: 11, color: colors.ink }}>{t('game_space')}</Text>\n          </Pressable>\n        </View>\n      </View>\n    );\n\n    if (gameType === 'main' && mysteryPlayer) {\n      return withBack(\n        <View style={{ flex: 1, backgroundColor: colors.bg, paddingTop: insets.top + 14 }}>\n          {timerBar}\n          <ScrollView contentContainerStyle={{ paddingHorizontal: 20, paddingTop: 10, gap: 5 }}>\n            {mysteryPlayer.clubs.map((c, i) => {\n              const rev = i < revealed;\n              if (rev) {\n                return (\n                  <RevealCard key={i}>\n                    <HardShadowBox bg={colors.card} radius={12} offset={3} style={{ marginBottom: 5 }}>\n                      <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8, padding: 6 }}>\n                        <ClubShield name={c} size={36} />\n                        <Text style={{ fontFamily: fonts.display, fontSize: 13, color: colors.ink, flex: 1 }}>{c}</Text>\n                      </View>\n                    </HardShadowBox>\n                  </RevealCard>\n                );\n              }\n              return (\n                <View key={i} style={{ flexDirection: 'row', alignItems: 'center', gap: 8, padding: 6, backgroundColor: colors.track, borderWidth: 2, borderColor: 'rgba(0,0,0,.2)', borderStyle: 'dashed', borderRadius: 12, marginBottom: 5 }}>\n                  <View style={{ width: 36, height: 36, borderRadius: 8, backgroundColor: colors.card, alignItems: 'center', justifyContent: 'center' }}>\n                    <Text style={{ fontFamily: fonts.display, fontSize: 14, color: colors.muted }}>?</Text>\n                  </View>\n                </View>\n              );\n            })}\n          </ScrollView>\n          {wrongList.length > 0 && (\n            <View style={{ paddingHorizontal: 20, paddingTop: 6, flexDirection: 'row', gap: 5, flexWrap: 'wrap' }}>\n              {wrongList.map((w, i) => (\n                <View key={i} style={{ paddingVertical: 3, paddingHorizontal: 9, backgroundColor: accent.wrongRed, borderWidth: 1.5, borderColor: colors.border, borderRadius: 999 }}>\n                  <Text style={{ fontFamily: fonts.bodySemibold, fontSize: 9, color: colors.ink }}>✕ {w}</Text>\n                </View>\n              ))}\n            </View>\n          )}\n          <View style={{ paddingHorizontal: 20, paddingTop: 8, paddingBottom: Math.max(12, insets.bottom + 8) }}>\n            <View style={{ backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12, paddingVertical: 10, paddingHorizontal: 12 }}>\n              <Text numberOfLines={1} style={{ fontFamily: fonts.displayBold, fontSize: 14, color: answer ? colors.ink : colors.muted }}>{answer || t('game_input_placeholder')}</Text>\n            </View>\n            {keyboard}\n            <Pressable onPress={submitGuess} style={{ marginTop: 8, paddingVertical: 12, backgroundColor: accent.coral, borderWidth: 2, borderColor: colors.border, borderRadius: 12, alignItems: 'center' }}>\n              <Text style={{ fontFamily: fonts.display, fontSize: 13, color: '#fff', letterSpacing: 1, textTransform: 'uppercase' }}>{t('game_send')}</Text>\n            </Pressable>\n          </View>\n        </View>,\n        { hideBack: true }\n      );\n    }\n\n    if (gameType === 'club' && mysteryClub) {\n      const revealFraction = 0.15 + 0.85 * (clubGuesses.length / MAX_GUESSES);\n      const clubNames = Object.keys(CLUB_DATA);\n      const suggestions =\n        answer.trim().length >= 2\n          ? clubNames.filter((n) => stripAcc(n.toLowerCase()).includes(stripAcc(answer.trim().toLowerCase()))).slice(0, 5)\n          : [];\n      return withBack(\n        <View style={{ flex: 1, backgroundColor: colors.bg, paddingTop: insets.top + 14 }}>\n          {timerBar}\n          <View style={{ alignItems: 'center', paddingVertical: 12 }}>\n            <Crest name={mysteryClub} revealFraction={revealFraction} />\n          </View>\n          <ScrollView contentContainerStyle={{ paddingHorizontal: 20, paddingBottom: 8 }}>\n            {clubGuesses.map((g) => (\n              <ClubGuessChips key={g.name} row={g} />\n            ))}\n          </ScrollView>\n          <View style={{ paddingHorizontal: 20, paddingTop: 8, paddingBottom: Math.max(12, insets.bottom + 8) }}>\n            <View style={{ backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12, paddingVertical: 10, paddingHorizontal: 12 }}>\n              <Text numberOfLines={1} style={{ fontFamily: fonts.displayBold, fontSize: 14, color: answer ? colors.ink : colors.muted }}>{answer || t('club_answer_placeholder')}</Text>\n            </View>\n            {suggestions.length > 0 && (\n              <View style={{ marginTop: 6, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12, overflow: 'hidden' }}>\n                {suggestions.map((s) => (\n                  <Pressable key={s} onPress={() => setAnswer(s)} style={{ paddingVertical: 8, paddingHorizontal: 14, borderBottomWidth: 1, borderBottomColor: 'rgba(0,0,0,.06)' }}>\n                    <Text style={{ fontFamily: fonts.displayBold, fontSize: 13, color: colors.ink }}>{s}</Text>\n                  </Pressable>\n                ))}\n              </View>\n            )}\n            {error && <Text style={{ fontFamily: fonts.bodySemibold, fontSize: 11, color: accent.coral, marginTop: 6 }}>{error}</Text>}\n            {keyboard}\n            <Pressable onPress={submitGuess} style={{ marginTop: 8, paddingVertical: 12, backgroundColor: accent.coral, borderWidth: 2, borderColor: colors.border, borderRadius: 12, alignItems: 'center' }}>\n              <Text style={{ fontFamily: fonts.display, fontSize: 13, color: '#fff', letterSpacing: 1, textTransform: 'uppercase' }}>{t('game_send')}</Text>\n            </Pressable>\n          </View>\n        </View>,\n        { hideBack: true }\n      );\n    }\n\n    if (gameType === 'liste' && mysteryList) {\n      const listeSuggestions =\n        answer.trim().length >= 2\n          ? mysteryList.players\n              .filter((_, i) => !foundIndexes.includes(i))\n              .filter((p) => stripAcc(playerFull(p).toLowerCase()).includes(stripAcc(answer.trim().toLowerCase())))\n              .slice(0, 5)\n          : [];\n      return withBack(\n        <View style={{ flex: 1, backgroundColor: colors.bg, paddingTop: insets.top + 14 }}>\n          {timerBar}\n          <Text style={{ textAlign: 'center', fontFamily: fonts.displayBold, fontSize: 14, color: colors.ink, marginTop: 8 }}>\n            {mysteryList.title} · {foundIndexes.length}/{mysteryList.players.length}\n          </Text>\n          {listPool === 'xi' ? (\n            <ScrollView contentContainerStyle={{ paddingHorizontal: 20, paddingTop: 10 }}>\n              <XIPitch players={mysteryList.players} foundIndexes={foundIndexes} />\n            </ScrollView>\n          ) : (\n            <ScrollView contentContainerStyle={{ paddingHorizontal: 20, paddingTop: 10, flexDirection: 'row', flexWrap: 'wrap', gap: 6 }}>\n              {mysteryList.players.map((p, i) => {\n                const found = foundIndexes.includes(i);\n                const photo = found ? playerPhoto(p) : undefined;\n                return (\n                  <View\n                    key={i}\n                    style={{ flexDirection: 'row', alignItems: 'center', gap: 6, paddingVertical: 6, paddingHorizontal: 10, borderRadius: 999, backgroundColor: found ? accent.mint : colors.track, borderWidth: 1.5, borderColor: colors.border }}\n                  >\n                    {photo && <PlayerPortrait name={photo} size={18} variant=\"avatar\" />}\n                    <Text style={{ fontFamily: fonts.mono, fontSize: 10, color: colors.ink }}>{found ? playerFull(p) : '?'}</Text>\n                  </View>\n                );\n              })}\n            </ScrollView>\n          )}\n          <View style={{ paddingHorizontal: 20, paddingTop: 8, paddingBottom: Math.max(12, insets.bottom + 8) }}>\n            <View style={{ backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12, paddingVertical: 10, paddingHorizontal: 12 }}>\n              <Text numberOfLines={1} style={{ fontFamily: fonts.displayBold, fontSize: 14, color: answer ? colors.ink : colors.muted }}>{answer || t('game_input_placeholder')}</Text>\n            </View>\n            {listeSuggestions.length > 0 && (\n              <View style={{ marginTop: 6, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12, overflow: 'hidden' }}>\n                {listeSuggestions.map((s) => (\n                  <Pressable key={playerFull(s)} onPress={() => setAnswer(playerFull(s))} style={{ paddingVertical: 8, paddingHorizontal: 14, borderBottomWidth: 1, borderBottomColor: 'rgba(0,0,0,.06)' }}>\n                    <Text style={{ fontFamily: fonts.displayBold, fontSize: 13, color: colors.ink }}>{playerFull(s)}</Text>\n                  </Pressable>\n                ))}\n              </View>\n            )}\n            {error && <Text style={{ fontFamily: fonts.bodySemibold, fontSize: 11, color: accent.coral, marginTop: 6 }}>{error}</Text>}\n            {keyboard}\n            <Pressable onPress={submitGuess} style={{ marginTop: 8, paddingVertical: 12, backgroundColor: accent.coral, borderWidth: 2, borderColor: colors.border, borderRadius: 12, alignItems: 'center' }}>\n              <Text style={{ fontFamily: fonts.display, fontSize: 13, color: '#fff', letterSpacing: 1, textTransform: 'uppercase' }}>{t('game_send')}</Text>\n            </Pressable>\n          </View>\n        </View>,\n        { hideBack: true }\n      );\n    }\n\n    if (gameType === 'grille' && grid) {\n      const filledCount = grilleCells.filter((c) => c).length;\n      const cellSuggestions =\n        answer.trim().length >= 2\n          ? PLAYERS.filter((p) => stripAcc(p.n.toLowerCase()).includes(stripAcc(answer.trim().toLowerCase()))).slice(0, 5)\n          : [];\n      return withBack(\n        <View style={{ flex: 1, backgroundColor: colors.bg, paddingTop: insets.top + 14 }}>\n          {timerBar}\n          <Text style={{ textAlign: 'center', fontFamily: fonts.displayBold, fontSize: 14, color: colors.ink, marginTop: 8 }}>\n            {filledCount}/9\n          </Text>\n          <View style={{ padding: 20 }}>\n            <View style={{ flexDirection: 'row' }}>\n              <View style={{ width: 70 }} />\n              {grid.cols.map((c, i) => (\n                <View key={i} style={{ flex: 1, alignItems: 'center', paddingBottom: 6, gap: 3 }}>\n                  {c.type === 'nat' && <Text style={{ fontSize: 24 }}>{flagEmoji(c.value)}</Text>}\n                  {c.type === 'club' && <ClubShield name={c.value} size={30} />}\n                  <Text style={{ fontFamily: fonts.displayBold, fontSize: 9, color: colors.ink, textAlign: 'center' }}>{criterionLabel(c, t)}</Text>\n                </View>\n              ))}\n            </View>\n            {grid.rows.map((r, ri) => (\n              <View key={ri} style={{ flexDirection: 'row', alignItems: 'center', marginBottom: 6 }}>\n                <View style={{ width: 70, paddingRight: 6, alignItems: 'center', gap: 3 }}>\n                  {r.type === 'club' && <ClubShield name={r.value} size={30} />}\n                  <Text style={{ fontFamily: fonts.displayBold, fontSize: 9, color: colors.ink, textAlign: 'center' }} numberOfLines={2}>{criterionLabel(r, t)}</Text>\n                </View>\n                {grid.cols.map((_, ci) => {\n                  const index = ri * 3 + ci;\n                  const cellName = grilleCells[index];\n                  return (\n                    <Pressable\n                      key={ci}\n                      onPress={() => {\n                        if (cellName) return;\n                        setGrilleSelectedCell(index);\n                        setAnswer('');\n                        setError(null);\n                      }}\n                      style={{ flex: 1, aspectRatio: 1, marginHorizontal: 3, borderRadius: 10, borderWidth: 2, borderColor: colors.border, alignItems: 'center', justifyContent: 'center', backgroundColor: cellName ? accent.mint : colors.card, padding: 4 }}\n                    >\n                      {cellName ? (\n                        <Text style={{ fontFamily: fonts.bodySemibold, fontSize: 9, color: '#1a1a1a', textAlign: 'center' }} numberOfLines={2}>{cellName}</Text>\n                      ) : (\n                        <Text style={{ fontFamily: fonts.display, fontSize: 16, color: colors.muted }}>+</Text>\n                      )}\n                    </Pressable>\n                  );\n                })}\n              </View>\n            ))}\n          </View>\n\n          <Modal visible={grilleSelectedCell !== null} transparent animationType=\"fade\" onRequestClose={() => setGrilleSelectedCell(null)}>\n            <Pressable style={{ flex: 1, backgroundColor: 'rgba(0,0,0,.45)', justifyContent: 'flex-end' }} onPress={() => setGrilleSelectedCell(null)}>\n              <Pressable style={{ backgroundColor: colors.bg, borderTopWidth: 2.5, borderColor: colors.border, borderTopLeftRadius: 20, borderTopRightRadius: 20, padding: 20, paddingBottom: Math.max(20, insets.bottom + 12) }}>\n                <View style={{ backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12, paddingVertical: 12, paddingHorizontal: 14 }}>\n                  <Text numberOfLines={1} style={{ fontFamily: fonts.displayBold, fontSize: 14, color: answer ? colors.ink : colors.muted }}>\n                    {answer || t('duel_answer_placeholder')}\n                  </Text>\n                </View>\n                {cellSuggestions.length > 0 && (\n                  <View style={{ marginTop: 6, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12, overflow: 'hidden' }}>\n                    {cellSuggestions.map((s) => (\n                      <Pressable key={s.n} onPress={() => setAnswer(s.n)} style={{ paddingVertical: 9, paddingHorizontal: 14, borderBottomWidth: 1, borderBottomColor: 'rgba(0,0,0,.06)' }}>\n                        <Text style={{ fontFamily: fonts.displayBold, fontSize: 13, color: colors.ink }}>{s.n}</Text>\n                      </Pressable>\n                    ))}\n                  </View>\n                )}\n                {error && <Text style={{ fontFamily: fonts.bodySemibold, fontSize: 11, color: accent.coral, marginTop: 8 }}>{error}</Text>}\n                {keyboard}\n                <Pressable onPress={submitGrilleCell} style={{ marginTop: 12, paddingVertical: 12, backgroundColor: accent.coral, borderRadius: 12, alignItems: 'center' }}>\n                  <Text style={{ fontFamily: fonts.display, fontSize: 13, color: '#fff' }}>{t('duel_validate')}</Text>\n                </Pressable>\n              </Pressable>\n            </Pressable>\n          </Modal>\n        </View>,\n        { hideBack: true }\n      );\n    }\n  }\n\n  // Finished: results.\n  const ranked = players\n    .filter((p) => p.status === 'joined')\n    .slice()\n    .sort((a, b) => {\n      if (gameType === 'liste') return b.found_count - a.found_count;\n      if (a.solved && b.solved) return (a.elapsed_ms || 0) - (b.elapsed_ms || 0);\n      if (a.solved) return -1;\n      if (b.solved) return 1;\n      if (gameType === 'grille') return b.found_count - a.found_count;\n      return b.attempts - a.attempts;\n    });\n  const medals = ['🥇', '🥈', '🥉'];\n  const revealLabel = gameType === 'main' ? game.mystery_player : gameType === 'club' ? game.mystery_club : null;\n  const othersJoined = players.filter((p) => p.status === 'joined' && p.user_id !== user?.id);\n  const rematch = () => {\n    if (othersJoined.length === 0) return;\n    setBusy(true);\n    createGroup(\n      othersJoined.map((p) => p.user_id),\n      othersJoined.map((p) => p.display_name),\n      game.round_seconds,\n      gameType\n    ).finally(() => setBusy(false));\n  };\n\n  return withBack(\n    <View style={{ flex: 1, backgroundColor: colors.bg, paddingTop: insets.top + 60, paddingHorizontal: 20 }}>\n      <ScrollView>\n        <Text style={{ fontFamily: fonts.display, fontSize: 22, color: colors.ink }}>{t('group_results_title')}</Text>\n        {revealLabel && (\n          <Text style={{ fontFamily: fonts.body, fontSize: 12, color: colors.muted, marginTop: 4 }}>\n            {t('group_results_sub')} {revealLabel}\n          </Text>\n        )}\n        {lastReward > 0 && (\n          <View style={{ marginTop: 12, alignSelf: 'flex-start', paddingVertical: 6, paddingHorizontal: 12, backgroundColor: accent.mint, borderWidth: 2, borderColor: colors.border, borderRadius: 999 }}>\n            <Text style={{ fontFamily: fonts.displayBold, fontSize: 13, color: colors.ink }}>+{lastReward} 💎</Text>\n          </View>\n        )}\n        <View style={{ marginTop: 16, gap: 8 }}>\n          {ranked.map((p, i) => (\n            <View key={p.id} style={{ flexDirection: 'row', alignItems: 'center', gap: 10, paddingVertical: 10, paddingHorizontal: 12, backgroundColor: p.user_id === user?.id ? accent.mint : colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12 }}>\n              <Text style={{ fontSize: 16 }}>\n                {gameType === 'liste'\n                  ? p.found_count > 0 && medals[i]\n                    ? medals[i]\n                    : p.found_count > 0\n                    ? '✅'\n                    : '—'\n                  : p.solved && medals[i]\n                  ? medals[i]\n                  : p.solved\n                  ? '✅'\n                  : '—'}\n              </Text>\n              <Text style={{ fontFamily: fonts.displayBold, fontSize: 13, color: colors.ink, flex: 1 }}>{p.display_name}</Text>\n              <Text style={{ fontFamily: fonts.mono, fontSize: 10, color: colors.muted }}>\n                {gameType === 'liste'\n                  ? `${p.found_count} ${t('group_found_short')}`\n                  : gameType === 'grille'\n                  ? p.solved\n                    ? `${Math.round((p.elapsed_ms || 0) / 1000)}s`\n                    : `${p.found_count}/9`\n                  : p.solved\n                  ? `${p.attempts} ${t('group_attempts_short')} · ${Math.round((p.elapsed_ms || 0) / 1000)}s`\n                  : t('group_not_found')}\n              </Text>\n            </View>\n          ))}\n        </View>\n      </ScrollView>\n      <View style={{ flexDirection: 'row', gap: 10, marginVertical: 12 }}>\n        {othersJoined.length > 0 && (\n          <Pressable\n            disabled={busy}\n            onPress={() => recordRoundPlayed(rematch)}\n            style={{ flex: 1, paddingVertical: 14, backgroundColor: '#1a1a1a', borderWidth: 2, borderColor: colors.border, borderRadius: 14, alignItems: 'center', opacity: busy ? 0.6 : 1 }}\n          >\n            <Text style={{ fontFamily: fonts.display, fontSize: 13, color: '#fff', letterSpacing: 0.5, textTransform: 'uppercase' }}>⚔️ {t('duel_rematch')}</Text>\n          </Pressable>\n        )}\n        <Pressable onPress={() => recordRoundPlayed(leaveFinished)} style={{ flex: 1, paddingVertical: 14, backgroundColor: accent.coral, borderWidth: 2, borderColor: colors.border, borderRadius: 14, alignItems: 'center' }}>\n          <Text style={{ fontFamily: fonts.display, fontSize: 13, color: '#fff', letterSpacing: 0.5, textTransform: 'uppercase' }}>{t('group_leave')}</Text>\n        </Pressable>\n      </View>\n    </View>\n  );\n}\n");
write("src/navigation/RootNavigator.tsx", "import React, { useEffect, useState } from 'react';\nimport AsyncStorage from '@react-native-async-storage/async-storage';\nimport { NavigationContainer, createNavigationContainerRef } from '@react-navigation/native';\nimport { createNativeStackNavigator } from '@react-navigation/native-stack';\nimport * as Notifications from 'expo-notifications';\nimport { supabase } from '../lib/supabase';\nimport { logEvent } from '../lib/analytics';\nimport { XI_MATCHES } from '../data/xiMatches';\nimport TabNavigator from './TabNavigator';\nimport OnboardingScreen from '../screens/OnboardingScreen';\nimport DailyScreen from '../screens/DailyScreen';\nimport SettingsScreen from '../screens/SettingsScreen';\nimport ShopScreen from '../screens/ShopScreen';\nimport MissionsScreen from '../screens/MissionsScreen';\nimport CollectionScreen from '../screens/CollectionScreen';\nimport PublicProfileScreen from '../screens/PublicProfileScreen';\n\nexport type RootStackParamList = {\n  Onboarding: undefined;\n  Tabs: undefined;\n  Daily: undefined;\n  Settings: undefined;\n  Shop: undefined;\n  Missions: undefined;\n  Collection: undefined;\n  PublicProfile: { userId: string };\n};\n\nconst Stack = createNativeStackNavigator<RootStackParamList>();\nconst ONBOARDING_KEY = 'strikr_onboarding_seen_v1';\n\nexport const navigationRef = createNavigationContainerRef<RootStackParamList>();\n\n// Tapping any of the 5 invite/social push notification types (foreground,\n// backgrounded, or cold-launch) routes to the relevant screen. For\n// duel_invite/xi_duel_invite, useDuel()/useXIDuel() already load the\n// invitee's most recent pending invite on mount, so no id needs to travel\n// through the deep link — same for group_invite via useGroupGame(), except\n// there the actual game TYPE (main/club/liste/grille, or the 'xi' variant of\n// liste) has to be resolved first so JeuxScreen renders the right screen\n// under it, since GroupGameScreen's rendering keys off the `gameType` prop\n// it's given, not off the loaded row.\nasync function openInviteFromNotification(data: unknown) {\n  const type = (data as any)?.type;\n  if (!type) return;\n\n  if (type === 'duel_invite') {\n    if (!navigationRef.isReady()) return;\n    navigationRef.navigate('Tabs' as never, { screen: 'Jeux', params: { mode: 'duel' } } as never);\n    return;\n  }\n  if (type === 'xi_duel_invite') {\n    if (!navigationRef.isReady()) return;\n    navigationRef.navigate('Tabs' as never, { screen: 'Jeux', params: { mode: 'duel', game: 'xi' } } as never);\n    return;\n  }\n  if (type === 'friend_request' || type === 'friend_request_accepted') {\n    if (!navigationRef.isReady()) return;\n    navigationRef.navigate('Tabs' as never, { screen: 'Friends' } as never);\n    return;\n  }\n  if (type === 'group_invite') {\n    const gameId = (data as any)?.game_id;\n    let game = 'main';\n    if (gameId) {\n      const { data: row } = await supabase.from('group_games').select('game_type, list_id').eq('id', gameId).maybeSingle();\n      if (row?.game_type === 'liste' && row.list_id && XI_MATCHES.some((m) => m.id === row.list_id)) {\n        game = 'xi';\n      } else if (row?.game_type) {\n        game = row.game_type;\n      }\n    }\n    // Diagnostic for the \"invitee taps the notification but lands on a\n    // create-room screen\" report — logs whether this tap resolved the\n    // right game id/type and whether the navigator was actually ready to\n    // act on it, instead of guessing from database timestamps alone.\n    supabase.auth.getUser().then(({ data: authData }) => {\n      const uid = authData?.user?.id;\n      if (uid) {\n        logEvent(uid, 'group_invite_tap_diagnostic', {\n          gameId: gameId ?? null,\n          resolvedGame: game,\n          navigatorReady: navigationRef.isReady(),\n        });\n      }\n    });\n    if (!navigationRef.isReady()) return;\n    navigationRef.navigate('Tabs' as never, { screen: 'Jeux', params: { mode: 'group', game } } as never);\n  }\n}\n\nexport default function RootNavigator() {\n  const [checked, setChecked] = useState(false);\n  const [seenOnboarding, setSeenOnboarding] = useState(true);\n\n  useEffect(() => {\n    AsyncStorage.getItem(ONBOARDING_KEY).then((v) => {\n      setSeenOnboarding(v === '1');\n      setChecked(true);\n    });\n  }, []);\n\n  useEffect(() => {\n    const sub = Notifications.addNotificationResponseReceivedListener((response) => {\n      openInviteFromNotification(response.notification.request.content.data);\n    });\n    return () => sub.remove();\n  }, []);\n\n  // Cold launch (app was killed, user tapped the notification to open it):\n  // the response is only safe to act on once the navigator has mounted, so\n  // this checks it in onReady rather than racing it against `checked` above.\n  const onNavigationReady = () => {\n    Notifications.getLastNotificationResponseAsync().then((response) => {\n      if (response) openInviteFromNotification(response.notification.request.content.data);\n    });\n  };\n\n  if (!checked) return null;\n\n  return (\n    <NavigationContainer ref={navigationRef} onReady={onNavigationReady}>\n      <Stack.Navigator screenOptions={{ headerShown: false }} initialRouteName={seenOnboarding ? 'Tabs' : 'Onboarding'}>\n        <Stack.Screen name=\"Onboarding\" component={OnboardingScreen} />\n        <Stack.Screen name=\"Tabs\" component={TabNavigator} />\n        <Stack.Screen name=\"Daily\" component={DailyScreen} options={{ presentation: 'card' }} />\n        <Stack.Screen name=\"Settings\" component={SettingsScreen} options={{ presentation: 'card' }} />\n        <Stack.Screen name=\"Shop\" component={ShopScreen} options={{ presentation: 'card' }} />\n        <Stack.Screen name=\"Missions\" component={MissionsScreen} options={{ presentation: 'card' }} />\n        <Stack.Screen name=\"Collection\" component={CollectionScreen} options={{ presentation: 'card' }} />\n        <Stack.Screen name=\"PublicProfile\" component={PublicProfileScreen} options={{ presentation: 'card' }} />\n      </Stack.Navigator>\n    </NavigationContainer>\n  );\n}\n");
